
.events {
  display: flex;
  flex-direction: column;
  padding: 14px 16px;
  border-top: 1px solid var(--c-border);
}

.event-list {
  --collapse-gap: 10px;
}

.event {
  padding: 14px 15px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  background: var(--c-surface);
}

.event:hover {
  border-color: var(--c-border-strong);
}

.event-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.event-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--c-text);
}

.event-time,
.event-deadline {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--c-bg-alt);
  color: var(--c-text-muted);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.event-theme {
  font-size: 12px;
  color: var(--c-text-faint);
}

.event-detail {
  margin-top: 6px;
  font-family: var(--f-serif);
  font-size: 14px;
  line-height: 1.75;
  color: var(--c-text-body);
}

.event-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
}

.option {
  display: flex;
  align-items: baseline;
  gap: 8px;
  width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-sm);
  background: var(--c-surface);
  cursor: pointer;
  text-align: left;
}

.option:hover {
  background: var(--c-surface-sunken);
  border-color: var(--c-border-strong);
}

.option-act {
  font-size: 13.5px;
  color: var(--c-text);
}

.option:hover .option-act {
  color: var(--c-accent-hover);
}

.option-cost {
  margin-left: auto;
  flex: none;
  font-size: 11.5px;
  color: var(--c-text-faint);
}
