
.skills {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
}

.group {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.group-label {
  font-size: 12px;
  color: var(--c-text-faint);
}

.skill-list {
  --collapse-gap: 11px;
}

.empty {
  font-size: 12.5px;
  color: var(--c-text-faint);
}
