
.level {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.level-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.level-name {
  font-size: 13px;
  color: var(--c-text);
}

.level-meta {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}

.level-meta b {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--c-accent-hover);
}

.level-pct {
  font-size: 11.5px;
  color: var(--c-text-muted);
}

.level-cap {
  font-size: 11px;
  color: var(--c-text-faint);
}

.level-track {
  display: flex;
  gap: 3px;
  height: 6px;
}

.level-cell {
  position: relative;
  flex: 1;
  border-radius: 2px;
  background: var(--c-border);
  overflow: hidden;
}

.level-cell.is-done {
  background: var(--c-accent);
}

.level-cell.is-capped {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--c-border);
}

.level-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  border-radius: 2px;
  background: var(--c-accent);
  transition: width 0.45s var(--ease-out);
}
