
.archive {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 16px;
}

.vitals {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.group {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.group-label {
  font-size: 12px;
  color: var(--c-text-faint);
}

.rel-list {
  --collapse-gap: 11px;
}

.empty {
  font-size: 12.5px;
  color: var(--c-text-faint);
}

.asset-groups {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.asset-group {
  display: flex;
  flex-direction: column;
  padding: 6px 12px 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-sm);
  background: var(--c-surface-sunken);
}

.asset-group-label {
  padding: 4px 0 6px;
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--c-text-faint);
}

.asset-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 9px 0;
  border-top: 1px solid var(--c-border);
}

.asset-row:first-child {
  border-top: none;
}

.asset-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.asset-name {
  font-size: 13px;
  color: var(--c-text);
}

.asset-source {
  font-size: 11.5px;
  color: var(--c-text-faint);
}

.asset-amount {
  margin-left: auto;
  flex: none;
  font-size: 13px;
  font-weight: 600;
  color: var(--c-accent-hover);
  font-variant-numeric: tabular-nums;
}
